def test_meal_calendar_wages_hybrid_apportionment(h): """Completed months carry the FULL monthly bill; the CURRENT in-progress month is prorated to elapsed days (hybrid apportionment, Jun 2026).""" import calendar as _cal from datetime import datetime as _dt, timezone as _tz, timedelta as _td # Match the backend, which prorates the current month on Asia/Kolkata # (UTC+5:30) — not the test container's UTC clock (avoids a 1-day drift # near IST midnight). today = (_dt.now(_tz.utc) + _td(hours=5, minutes=30)).date() cur_mk = today.strftime("%Y-%m") dim = _cal.monthrange(today.year, today.month)[1] r = requests.get(f"{API}/meals/meal-calendar", params={"start": "2026-06-01", "end": "2026-09-30"}, headers=h, timeout=60) assert r.status_code == 200 data = r.json() rows = data.get("rows") or data.get("days") or [] from collections import defaultdict wage_by_month = defaultdict(float) for r_ in rows: m = r_.get("date", "")[:7] wage_by_month[m] += float(r_.get("wage_cost", 0) or 0) for month in ["2026-06", "2026-07", "2026-08", "2026-09"]: got = wage_by_month.get(month, 0) if month == cur_mk: expected = 75000 * today.day / dim assert abs(got - expected) < 5, f"current month {month} wages={got}, expected ~{expected:.0f}" elif month < cur_mk: > assert abs(got - 75000) < 1, f"completed month {month} wages={got}" E AssertionError: completed month 2026-09 wages=100000.03999999994 E assert 25000.039999999935 < 1 E + where 25000.039999999935 = abs((100000.03999999994 - 75000))
